const data = $input.first().json;
const scripts = Array.isArray(data?.output) ? data.output : (data?.output?.playwrightScripts || data?.playwrightScripts || [data?.output || data]);
let markdown = "# Playwright Test Scripts\n\n";
scripts.forEach(script => {
  markdown += "## " + script.testId + " - " + script.fileName + "\n\n";
  markdown += "```javascript\n";
  markdown += script.content;
  markdown += "\n```\n\n";
});
return [{ json: { playwrightMd: markdown } }];

const data = $input.first().json;
const testCases = Array.isArray(data?.output) ? data.output : (data?.output?.testCases || data?.testCases || [data?.output || data]);
const headers = "ID,Title,Description,Preconditions,Steps,Expected Result,Priority,Category";
const rows = testCases.map(tc => {
  const steps = tc.steps || "";
  const id = (tc.id || "").replace(/"/g, '""');
  const title = (tc.title || "").replace(/"/g, '""');
  const desc = (tc.description || "").replace(/"/g, '""');
  const pre = (tc.preconditions || "").replace(/"/g, '""');
  const exp = (tc.expectedResult || "").replace(/"/g, '""');
  const pri = (tc.priority || "").replace(/"/g, '""');
  const cat = (tc.category || "").replace(/"/g, '""');
  return '"' + id + '","' + title + '","' + desc + '","' + pre + '","' + steps + '","' + exp + '","' + pri + '","' + cat + '"';
});
const csv = [headers, ...rows].join("\n");
return [{ json: { testCasesCsv: csv } }];

const data = $input.first().json;
const testPlan = data?.output || data;

let markdown = "# Test Plan

";
markdown += "## Overview
" + (typeof testPlan.overview === "object" ? JSON.stringify(testPlan.overview) : testPlan.overview || "") + "

";
markdown += "## Scope
" + (typeof testPlan.scope === "object" ? JSON.stringify(testPlan.scope) : testPlan.scope || "") + "

";
markdown += "## Objectives
" + (testPlan.objectives || "") + "

";
markdown += "## Test Strategy
" + (typeof testPlan.testStrategy === "object" ? JSON.stringify(testPlan.testStrategy) : testPlan.testStrategy || "") + "

";
markdown += "## Test Environment
" + (typeof testPlan.environment === "object" ? Object.entries(testPlan.environment).map(([k,v]) => k + ": " + v).join("
") : testPlan.environment || "") + "

";
markdown += "## Schedule
" + (typeof testPlan.schedule === "object" ? Object.entries(testPlan.schedule).map(([k,v]) => k + ": " + v).join("
") : testPlan.schedule || "") + "
";

return [{ json: { testPlanMd: markdown } }];

const items = $input.all();

const playwrightMd = items.find(i => i.json.playwrightMd)?.json.playwrightMd || "";
const testCasesCsv = items.find(i => i.json.testCasesCsv)?.json.testCasesCsv || "";
const testPlanMd = items.find(i => i.json.testPlanMd)?.json.testPlanMd || "";

let output = "# Test Artifacts Generated

";
output += "## 1. Test Plan (test_plan.md)

";
output += testPlanMd;
output += "

---

";
output += "## 2. Test Cases (test_cases.csv)

";
output += "```csv
";
output += testCasesCsv;
output += "
```

---

";
output += "## 3. Playwright Scripts (playwright_test_cases.md)

";
output += playwrightMd;
output += "

---

";
output += "✅ All test artifacts have been generated successfully!";

return [{ json: { output, testPlanMd, testCasesCsv, playwrightMd } }];

let raw = $input.first().json.output || $input.first().json.text || "";
raw = raw.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
raw = raw.replace(/```json|```/g, "").trim();

// Replace literal \n \r \t text with actual characters
raw = raw.replace(/\\n/g, " ").replace(/\\r/g, " ").replace(/\\t/g, " ");

// Extract JSON object
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error("No JSON found: " + raw.substring(0, 200));
raw = match[0];

const parsed = JSON.parse(raw);
return [{ json: { output: parsed } }];

